    const dest = pick(game.rng, [PLACES.beach, PLACES.bank, PLACES.hospital, PLACES.oldTown, PLACES.docks, PLACES.safehouse]);
    this.taxi = {
      phase: 'pickup',
      pickup: { x: rp.x, y: rp.y },
      dest: { x: dest.x, y: dest.y, name: dest.name },
      fare: 80 + Math.floor(game.rng() * 90),
      timer: 90,
