    const t = this.taxi;
    const p = game.player;
    t.timer -= dt;
    if (t.timer <= 0) { game.hud.toast('Fare cancelled — too slow.'); this.taxi = null; this.taxiCooldown = 25; return; }
    if (t.phase === 'pickup') {
      if (p.inCar && dist(p.x, p.y, t.pickup.x, t.pickup.y) < 80) {
        t.phase = 'dropoff';
