  objectiveText() {
    if (this.active) {
      const step = this.active.def.steps[this.active.step];
      if (step) return { title: this.active.def.title, text: step.text, timer: this.active.timer > 0 ? this.active.timer : (this.race ? this.race.timer : 0) };
