  idleMarker() {
    if (this.active || this._restartPending || this.completed >= MISSIONS.length) return null;
    return { x: PLACES.garage.x, y: PLACES.garage.y, color: '#7ee787', label: 'Start: ' + this.currentDef.title };
  }
